// Validate required fields from the webhook body.
// company_id / role are NEVER accepted here — they come from the
// server-side DB lookup in the Next.js route.
const body = $input.first().json.body ?? $input.first().json;

const required = ['email', 'fileName', 'fileBase64', 'title', 'visibility'];
const missing = required.filter(k => !body[k]);

if (missing.length > 0) {
  throw new Error(`Missing required fields: ${missing.join(', ')}`);
}

const validVisibility = ['company', 'department', 'restricted'];
if (!validVisibility.includes(body.visibility)) {
  throw new Error(`visibility must be one of: ${validVisibility.join(', ')}`);
}

// Pass validated fields only — never forward unknown fields.
return [{
  json: {
    email: body.email,
    fileName: body.fileName,
    fileBase64: body.fileBase64,
    title: body.title,
    visibility: body.visibility,
    description: body.description ?? null,
    departmentId: body.departmentId ?? null,
    reviewDate: body.reviewDate ?? null,
    documentId: body.documentId ?? null,
    _startedAt: new Date().toISOString()
  }
}];

const res = $input.first().json;
const body = res.body ?? res;
const startedAt = $('Validate Input').first().json._startedAt;
const finishedAt = new Date().toISOString();

return [{
  json: {
    ok: true,
    status: body.status,
    documentId: body.documentId,
    documentVersionId: body.documentVersionId,
    ingestionJobId: body.ingestionJobId,
    chunkCount: body.chunkCount,
    published: false,
    note: body.note,
    startedAt,
    finishedAt
  }
}];

const res = $input.first().json;
const body = res.body ?? res;
const startedAt = $('Validate Input').first().json._startedAt;
const finishedAt = new Date().toISOString();

// Map HTTP status + error code to a human-readable category.
const statusCode = res.statusCode ?? 0;
let category = 'INGESTION_FAILED';
if (statusCode === 401 || statusCode === 403) category = 'AUTH_ERROR';
else if (statusCode === 400) category = 'VALIDATION_ERROR';
else if (statusCode === 404) category = 'NOT_FOUND';
else if (statusCode === 503) category = 'SERVICE_UNAVAILABLE';
else if (statusCode >= 500) category = 'SERVER_ERROR';
else if (body.code) category = body.code;

return [{
  json: {
    ok: false,
    category,
    httpStatus: statusCode,
    error: body.error ?? 'Unknown error',
    errorCode: body.code ?? null,
    startedAt,
    finishedAt
  }
}];
